# ספריית ציורים פשוטים (וקטוריים) למילים – קואורדינטות 0..100, y כלפי מטה. כל ציור = רשימת קווים (רשימות נקודות)
import math
def arc(cx, cy, rx, ry, a0=0, a1=360, n=None):
    n = n or max(8, int(abs(a1 - a0) / 8))
    return [(cx + rx * math.cos(math.radians(a0 + (a1 - a0) * i / n)), cy + ry * math.sin(math.radians(a0 + (a1 - a0) * i / n))) for i in range(n + 1)]
def C(cx, cy, r): return arc(cx, cy, r, r)
def E(cx, cy, rx, ry, a0=0, a1=360): return arc(cx, cy, rx, ry, a0, a1)
def R(x, y, w, h): return [(x, y), (x + w, y), (x + w, y + h), (x, y + h), (x, y)]
def L(*p): return list(p)
def star(cx, cy, r1, r2, n=5, rot=-90):
    pts = [(cx + (r1 if i % 2 == 0 else r2) * math.cos(math.radians(rot + 180 * i / n)), cy + (r1 if i % 2 == 0 else r2) * math.sin(math.radians(rot + 180 * i / n))) for i in range(2 * n)]
    return pts + [pts[0]]
def bez(p0, p1, p2, n=12): return [((1-t)**2*p0[0]+2*(1-t)*t*p1[0]+t*t*p2[0], (1-t)**2*p0[1]+2*(1-t)*t*p1[1]+t*t*p2[1]) for t in [i/n for i in range(n+1)]]
def wave(x0, x1, y, a, k=2, n=30): return [(x0 + (x1 - x0) * i / n, y + a * math.sin(k * 2 * math.pi * i / n)) for i in range(n + 1)]
def heart(cx, cy, s):
    return [(cx + s * 16 * math.sin(t) ** 3 / 16, cy - s * (13 * math.cos(t) - 5 * math.cos(2 * t) - 2 * math.cos(3 * t) - math.cos(4 * t)) / 16) for t in [2 * math.pi * i / 48 for i in range(49)]]
def cloud(cx, cy, rx, ry):
    return [(cx + (rx + 6 * abs(math.sin(3 * t))) * math.cos(t), cy + (ry + 5 * abs(math.sin(3 * t))) * math.sin(t)) for t in [2 * math.pi * i / 60 for i in range(61)]]
def spiral(cx, cy, r, turns=2.5):
    n = 60; return [(cx + r * i / n * math.cos(turns * 2 * math.pi * i / n), cy + r * i / n * math.sin(turns * 2 * math.pi * i / n)) for i in range(n + 1)]

